"""One accessory piece, generated by itself and worn whole on an accessory slot: a duty belt on the belt slot.

An outfit is carried onto a body bone by bone and cut at the joints (`bake`). An accessory is neither: it is one
closed piece that rides on one bone. Its brief says so (`"accessory": "belt"`, `brief.py`), it is generated as
any model is (`generate`), and this module does the rest in two steps.

`prepare` is the body's to share: the generated piece is stood level (`level`), laid out, and its colours and
relief are read off the generation, all in the piece's own frame. What it keeps (`store`) is the same for every
body, so every body's tint texture is the same bytes and the pack keeps it once.

`fit` is each body's own: the kept piece is put round that body as it wears an outfit (`wrap`), written at its
part number, and gated (`gates`). A belt is wrapped, not scaled along axes: its hoop is brought to the outfit's
own outline round the hips, direction by direction, so it lies on a Dwarf's waist as on a Human's and its
pouches keep their depth.
"""
import json
import shutil
from pathlib import Path

import numpy as np

from tools.headkit import gltf

from . import bake as baking
from . import brief, export, measure, registry, repose, seams, texture
from .registry import require

KIND = 'srn-armorkit-accessory'
STRAP_ROUNDS = 8  # times a hoop is levelled again by its strap alone (`level`)
AXIS_ROUNDS = 5  # times a hoop is then stood by the way its strap's inner faces look (`level`)
INWARD = 0.7  # a face looks at the hoop's axis when its normal lies this much along the way there
AXIS_DEPTH = 1.15  # and is the strap's when it lies within this many times the least radius of such faces in its direction
STRAP_DEPTH = 1.08  # the strap: what lies within this many times the hoop's least radius in its direction
BODY_SIDE = 0.2  # of a belt's face normal toward the hoop's axis: past this the face lies against the body and is no metal's
BUDGET = {'triangles': 8000, 'texture': 1024}  # docs/armorkit/plan.md, Budgets: an accessory (user decision 2026-11-25, from 4,000)
DIRECTIONS = 96  # a belt is fitted in this many directions round the body's axis
LEVELS = 0.01  # metres: and in bands this tall along it
CLEARANCE = 0.004  # metres a belt's inner face stands outside what is worn under it
INSIDE = 0.002  # metres a point of a fitted belt may still stand inside what is worn under it (`gates`)
WORN_UNDER = ('pelvis', 'legl', 'legr')  # the parts a belt lies on: the trousers. A shirt's hem hangs over its top edge and is not gone
# round (put round Street Casual's blousing hem the strap stood 4 cm off the trousers a side; user, 2026-11-25: "still too large"); the arms hang beside it
DROP = 0.03  # metres below the waist joint a belt's band is centred by default: the trousers' waistband
SURFACE = 0.004  # metres: what is worn under a belt is sampled this densely
SPAN = {'belt': 0.42, 'neck': 0.26}  # metres across, about, as a Human wears the piece: what its texture is sized for
BAND = 0.05  # metres tall a duty belt's band is worn: a belt drawn daintier is made taller and deeper to it, not longer round
TALLER = 1.8  # by this much at most
DEEPER = 1.2  # and deeper by this much at most: on a narrow body the pouches would else stand off the hips like a hoop
GRID = 4  # a face of the hoop is read at the points of a grid this many steps along each edge
EVEN = 2.0  # directions: the fit is evened over this many each way, so that a pouch is not bent to a fold of cloth
CALM = {'neck': (8.0, 20.0)}  # degrees: on a hard shell, relief tilted less than the first is laid flat, and from the second on kept whole
KEYS = ('v', 'f', 'uv', 'n', 'rgb', 'covered', 'relief', 'src')  # what `store` keeps of a prepared piece


def _unit(vector):
    return vector / np.linalg.norm(vector)


def level(vertices, faces, rounds=30):
    """(points, turn): a hoop stood level, its plane the one most of its surface lies nearest to.

    A belt is drawn from a little above so that its hoop shows open, and comes out of the generator tilted
    that way. The plane is fitted by area with each face weighted down by its distance from it, so that a
    holster hanging off one side does not tip the fit as it would a plain least-squares one. The hoop is turned
    the shortest way onto the horizontal, about its own middle, which leaves its front where the camera saw it;
    up stays up, the tilt being less than a quarter turn."""
    points, faces = np.asarray(vertices, float), np.asarray(faces, int)
    a, b, c = (points[faces[:, k]] for k in range(3))
    area, middle = np.linalg.norm(np.cross(b - a, c - a), axis=1) / 2, (a + b + c) / 3
    weight = area.copy()
    for _ in range(rounds):
        centre = (weight[:, None] * middle).sum(axis=0) / weight.sum()
        spread = (middle - centre).T @ ((middle - centre) * weight[:, None])
        normal = np.linalg.eigh(spread)[1][:, 0]
        weight = area / np.maximum(np.abs((middle - centre) @ normal), 1e-3)
    normal = normal if normal[2] > 0 else -normal
    up = np.array([0.0, 0.0, 1.0])
    turn = repose.turn(normal, up)
    # Then by its strap alone: in each direction round the axis the hoop's innermost surface, which is the strap's
    # inner face whatever hangs off it. Two pouches at the front of Street Casual's belt, most of its surface, tipped
    # the fit above 18 degrees: its buckle sat 14 cm higher than its back and it was wrapped wide round the shirt's
    # hem (2026-11-25).
    for _ in range(STRAP_ROUNDS):
        stood = (points - centre) @ turn.T
        radius = np.hypot(stood[:, 0], stood[:, 1])
        way = np.floor((np.arctan2(stood[:, 1], stood[:, 0]) + np.pi) / (2 * np.pi) * DIRECTIONS).astype(int) % DIRECTIONS
        least = np.full(DIRECTIONS, np.inf)
        np.minimum.at(least, way, radius)
        strap = radius <= STRAP_DEPTH * least[way]
        count = np.bincount(way[strap], minlength=DIRECTIONS)
        if (count > 0).sum() < DIRECTIONS // 2:
            break  # no hoop to speak of: left as its surface lies
        mean = np.stack([np.bincount(way[strap], weights=stood[strap][:, k], minlength=DIRECTIONS) for k in range(3)], axis=1)[count > 0] / count[count > 0, None]
        slope = np.linalg.lstsq(np.c_[mean[:, :2], np.ones(len(mean))], mean[:, 2], rcond=None)[0]
        centre = centre + turn.T @ np.append(mean[:, :2].mean(axis=0), mean[:, 2].mean())  # the strap's own middle, not the pouches'
        turn = repose.turn(_unit(np.array([-slope[0], -slope[1], 1.0])), up) @ turn
    # And last by the way the strap's inner faces look: each looks at the hoop's axis, so the axis is the direction
    # most nearly square to them all. The strap's height where it is innermost says less: by it Street Casual's belt
    # still leaned back 9 degrees, its back edge 3 cm lower than its front, the buckle and the pouches' backs being
    # innermost and taller at the front (user, 2026-11-25: "still looks a little tilted backwards").
    square = np.cross(b - a, c - a)
    square = square / np.maximum(np.linalg.norm(square, axis=1, keepdims=True), 1e-12)
    for _ in range(AXIS_ROUNDS):
        stood, looks = (middle - centre) @ turn.T, square @ turn.T
        radius = np.maximum(np.hypot(stood[:, 0], stood[:, 1]), 1e-9)
        inward = np.abs((looks[:, :2] * stood[:, :2]).sum(axis=1)) / radius > INWARD  # either way round: a generated mesh is wound both
        way = np.floor((np.arctan2(stood[:, 1], stood[:, 0]) + np.pi) / (2 * np.pi) * DIRECTIONS).astype(int) % DIRECTIONS
        least = np.full(DIRECTIONS, np.inf)
        np.minimum.at(least, way[inward], radius[inward])
        strap = inward & (radius <= AXIS_DEPTH * least[way])
        if len(np.unique(way[strap])) < DIRECTIONS // 2:
            break
        axis = np.linalg.eigh((looks[strap] * area[strap, None]).T @ looks[strap])[1][:, 0]
        turn = repose.turn(axis if axis[2] > 0 else -axis, up) @ turn
    # Its middle is the middle of its band: where the hoop spans least from top to bottom, pouches apart (`wrap`).
    # Set by its surface, Street Casual's band stood 2.5 cm above where the fit put the hoop, round the shirt's hem.
    stood = (points - centre) @ turn.T
    way = np.floor((np.arctan2(stood[:, 1], stood[:, 0]) + np.pi) / (2 * np.pi) * DIRECTIONS).astype(int) % DIRECTIONS
    low, high = np.full(DIRECTIONS, np.inf), np.full(DIRECTIONS, -np.inf)
    np.minimum.at(low, way, stood[:, 2])
    np.maximum.at(high, way, stood[:, 2])
    held = np.isfinite(low)
    band = held & (high - low <= np.percentile((high - low)[held], 20))
    stood[:, 2] -= float(np.median(((low + high) / 2)[band]))
    return stood, turn


def _cells(points, directions=DIRECTIONS, levels=LEVELS):
    """(direction, level, radius) of points about the vertical axis through the origin."""
    angle = np.arctan2(points[:, 1], points[:, 0])
    return (np.floor((angle + np.pi) / (2 * np.pi) * directions).astype(int) % directions,
            np.floor(points[:, 2] / levels).astype(int), np.hypot(points[:, 0], points[:, 1]))


def _evened(values, width=EVEN):
    """A value per direction, evened round the circle, and nowhere less than it was."""
    count = len(values)
    reach = int(np.ceil(3 * width))
    kernel = np.exp(-0.5 * (np.arange(-reach, reach + 1) / width) ** 2)
    half = reach // 2  # the same each way: `-reach // 2` rounds an odd reach down on one side only
    widest = np.max([np.roll(values, shift) for shift in range(-half, half + 1)], axis=0)
    padded = np.concatenate([widest[-reach:], widest, widest[:reach]])
    return np.maximum(np.convolve(padded, kernel / kernel.sum(), mode='valid')[:count], values)


def _filled(values):
    """A value per direction with the directions that have none read from those beside them."""
    known = np.isfinite(values)
    require(known.any(), 'Nothing is worn under the belt at its height')
    index = np.arange(len(values))
    return np.interp(index, np.concatenate([index[known] - len(values), index[known], index[known] + len(values)]), np.tile(values[known], 3))


def wrap(points, faces, under, centre, clearance=CLEARANCE):
    """(points, record): a level hoop put round what is worn under it.

    `points` and `faces` are the hoop's, level about its own middle (`level`); `under` are (vertices, faces) of the parts
    worn under it, in body space; `centre` is where the middle of the hoop's band goes, on the body's axis.
    The hoop is first scaled as a whole, so that its inner outline is as long round as the outline of what is
    worn under it at the band's height: its band and pouches keep their proportions. Then each direction round
    the axis is moved in or out as one column, by as much as brings the hoop's inner face there `clearance`
    outside the widest of what lies under it at any height the hoop has surface in that direction, a holster
    down the thigh too. The move is evened round the circle and never less than a direction asks. Before it, a
    hoop whose band is less than `BAND` tall is made taller to it (`TALLER` at most) and deeper (`DEEPER` at most):
    heights and how far each point stands off the inner face grow, lengths round the hoop do not."""
    points, centre = np.asarray(points, float), np.asarray(centre, float)
    worn = np.concatenate([measure.surface_points(np.asarray(v, float), np.asarray(f, int), SURFACE) for v, f in under]) - centre
    way, height, radius = _cells(worn)
    inner = np.full(DIRECTIONS, np.inf)
    hoop_way, _, hoop_radius = _cells(points)
    np.minimum.at(inner, hoop_way, hoop_radius)
    inner = _filled(np.where(np.isfinite(inner), inner, np.nan))
    # the band is where most of the hoop's surface is: the levels within the middle half of its points
    low, high = np.percentile(points[:, 2], [25, 75])
    scale = 1.0
    for _ in range(2):  # the band's height depends on the scale, and the scale on what lies at the band's height
        band = (height >= np.floor(low * scale / LEVELS)) & (height <= np.floor(high * scale / LEVELS))
        outline = np.full(DIRECTIONS, -np.inf)
        np.maximum.at(outline, way[band], radius[band])
        outline = _filled(np.where(np.isfinite(outline), outline, np.nan))
        scale = float((outline.mean() + clearance) / inner.mean())
    placed = points * scale
    hoop_way, hoop_level, hoop_radius = _cells(placed)
    # the band's own height: the least the hoop spans in a direction, pouches apart (the fifth of directions with least)
    low_at, high_at = np.full(DIRECTIONS, np.inf), np.full(DIRECTIONS, -np.inf)
    np.minimum.at(low_at, hoop_way, placed[:, 2])
    np.maximum.at(high_at, hoop_way, placed[:, 2])
    spans = (high_at - low_at)[np.isfinite(low_at)]
    taller = float(np.clip(BAND / max(float(np.percentile(spans, 20)), 1e-6), 1.0, TALLER))
    angle = (np.arctan2(placed[:, 1], placed[:, 0]) + np.pi) / (2 * np.pi) * DIRECTIONS - 0.5
    first = np.floor(angle).astype(int)
    share = angle - first
    face = scale * ((1 - share) * inner[first % DIRECTIONS] + share * inner[(first + 1) % DIRECTIONS])  # the inner face in each point's direction
    deeper = np.maximum(face + (hoop_radius - face) * min(taller, DEEPER), 1e-6) / np.maximum(hoop_radius, 1e-6)
    placed = np.stack([placed[:, 0] * deeper, placed[:, 1] * deeper, placed[:, 2] * taller], axis=1)
    hoop_way, hoop_level, hoop_radius = _cells(placed)
    table = {}
    for key, value in zip(zip(way.tolist(), height.tolist()), radius.tolist()):
        if value > table.get(key, 0.0):
            table[key] = value
    grid = np.array([(i, j, GRID - i - j) for i in range(GRID + 1) for j in range(GRID + 1 - i)], float) / GRID  # points over each face
    faces = np.asarray(faces, int)
    moved = np.zeros(DIRECTIONS)
    for again in range(3):  # a move changes which level a slanting face lies over what: read again until nothing is left inside
        over = np.einsum('gk,fkc->fgc', grid, placed[faces]).reshape(-1, 3)  # the hoop's surface, not its corners alone
        hoop_way, hoop_level, hoop_radius = _cells(over)
        least = {}
        for key, value in zip(zip(hoop_way.tolist(), hoop_level.tolist()), hoop_radius.tolist()):
            if value < least.get(key, np.inf):
                least[key] = value
        move = np.full(DIRECTIONS, -np.inf)
        for (direction, band_level), value in least.items():
            if (direction, band_level) in table:
                move[direction] = max(move[direction], table[(direction, band_level)] + clearance - value)
        move = _filled(np.where(np.isfinite(move), move, np.nan))
        move = _evened(np.maximum(move, 0.0) if again else move)  # after the first, only outward
        shift = (1 - share) * move[first % DIRECTIONS] + share * move[(first + 1) % DIRECTIONS]
        radius = np.hypot(placed[:, 0], placed[:, 1])
        grown = np.maximum(radius + shift, 1e-6) / np.maximum(radius, 1e-6)
        placed = np.stack([placed[:, 0] * grown, placed[:, 1] * grown, placed[:, 2]], axis=1)
        moved = moved + move
    move, placed = moved, placed + centre
    return placed, {'scale': round(scale, 4), 'taller': round(taller, 3), 'moved': [round(float(move.min()), 4), round(float(move.max()), 4)]}


def calm(relief, least, whole):
    """A relief map with its slight tilts laid flat: under `least` degrees gone, from `whole` degrees on as read.

    The generator's surface is terraced, and on a broad smooth shell the terraces came through the relief as
    rings of contour lines, in the shading and in the tint's shade (respirator, 2026-11-17). A filter's rim or
    a visor's edge tilts far more and is kept."""
    normal = np.asarray(relief, float) * 2 - 1
    tilt = np.hypot(normal[..., 0], normal[..., 1])
    low, high = np.sin(np.radians(least)), np.sin(np.radians(whole))
    share = np.clip((tilt - low) / (high - low), 0.0, 1.0)
    share = share * share * (3 - 2 * share)
    flat = normal[..., :2] * share[..., None]
    up = np.sqrt(np.maximum(1 - (flat ** 2).sum(axis=-1), 0.0))
    return (np.concatenate([flat, up[..., None]], axis=-1) + 1) / 2


def prepare(document, mesh, colours, raw, xatlas, say=lambda *_: None):
    """(piece, whole): a generated accessory in its own frame, level, laid out, with its colours and relief.

    `document` is its brief, `mesh` its exported mesh, `colours` the saved colour field of its appearance job
    and `raw` the generator's own high-detail mesh. `piece` holds the laid-out mesh (`v`, `f`, `uv`, `n`), its
    colours and relief per texel (`rgb`, `covered`, `relief`) and where each vertex lies on the generated mesh
    (`src`); `whole` is what `bake.surface` finds of holes and loose pieces on the mesh as generated."""
    require(document.get('accessory') in SPAN, f'An accessory prepared this way is worn on one of {sorted(SPAN)}')
    source, faces = repose.load(mesh)
    require(len(faces) <= BUDGET['triangles'], f'The mesh has {len(faces)} triangles: export it at {BUDGET["triangles"]} or fewer')
    whole = baking.surface(source, faces)
    # a belt is stood level; headgear is drawn straight from the front and stays as generated (`headgear.conform` places it)
    levelled = level(source, faces)[0] if document['accessory'] == 'belt' else source - (source.min(axis=0) + source.max(axis=0)) / 2
    field, levels = texture.open_field(colours)
    read = lambda points: texture.read_field(field, levels, points)
    raw_v, raw_f = gltf.positions(raw)
    fine, fine_levels = texture.normal_field(np.asarray(raw_v), np.asarray(raw_f))
    read_fine = lambda points: texture.read_field(fine, fine_levels, points)
    in_field = baking.to_field(source)
    worn_size = SPAN[document['accessory']] / float(np.ptp(levelled, axis=0).max())  # the generation has no scale of its own
    mapping, faces, uv, size = texture.laid_out(xatlas, levelled * worn_size, faces, BUDGET['texture'])
    v, src = levelled[mapping], in_field[mapping]
    src_normals = export.vertex_normals(src, faces)
    rgb, covered, missed = texture.colour_map(uv, faces, src, read, size)
    relief, _, lost = texture.normal_map(uv, faces, src, src_normals, v, read_fine, size, added=np.zeros(len(faces), bool))
    if document['accessory'] in CALM:
        relief = calm(relief, *CALM[document['accessory']])
    say(f'{size} px, {len(faces)} faces, covered {covered.mean():.0%}, no colour {missed}, no normal {lost}')
    return {'v': v, 'f': faces, 'uv': uv, 'n': export.vertex_normals(v, faces), 'rgb': rgb, 'covered': covered, 'relief': relief, 'src': src}, whole


def store(piece, folder, whole=None):
    """Keep a prepared piece in `folder`, for `fit` to put on any body."""
    folder = Path(folder)
    folder.mkdir(parents=True, exist_ok=True)
    np.savez_compressed(folder / 'piece.npz', **{key: piece[key] for key in KEYS})
    (folder / 'piece.json').write_text(json.dumps({'schemaVersion': 1, 'kind': KIND, 'surface': whole}, indent=1) + '\n', encoding='utf-8', newline='\n')


def stored(folder):
    """(piece, whole) as `store` kept them."""
    folder = Path(folder)
    record = json.loads((folder / 'piece.json').read_text(encoding='utf-8'))
    require(record.get('kind') == KIND, f'{folder} holds no prepared accessory')
    with np.load(folder / 'piece.npz') as held:
        return {key: held[key] for key in KEYS}, record.get('surface')


def body_side(piece, document, tinted_on, size):
    """Per texel, the material a belt's faces turned toward the body are drawn in where their colours show a
    metal, and -1 elsewhere (`texture.tint_maps`' `trim`); None for a piece that has no such faces or no
    material to give them.

    A belt is drawn in one view, from the front and a little above. What that view never shows, the strap's
    inner face and the backs of its pouches, the generator paints near-black, and so it paints the buckle
    and the studs: Street Casual's belt showed two materials, and a fifth of it, leather lying against the
    body, was tinted on the buckle's metal channel (2026-11-25; the metal channels are for metal, and draw
    shiny). No metal lies between a belt and its wearer: a face whose normal points more than `BODY_SIDE`
    toward the hoop's axis takes the commonest material tinted on no metal."""
    plain = [k for k, kind in enumerate(tinted_on) if kind != 'metal']
    if document.get('accessory') != 'belt' or not plain or len(plain) == len(tinted_on):
        return None
    v, f = np.asarray(piece['v'], float), np.asarray(piece['f'], int)
    corners = v[f]
    normal = np.cross(corners[:, 1] - corners[:, 0], corners[:, 2] - corners[:, 0])
    out = (corners.mean(axis=1) - (v.min(axis=0) + v.max(axis=0)) / 2) * [1.0, 1.0, 0.0]
    toward = -(normal * out).sum(axis=1) / np.maximum(np.linalg.norm(normal, axis=1) * np.linalg.norm(out, axis=1), 1e-12)
    return np.where(texture.face_texels(piece['uv'], f, toward > BODY_SIDE, size), plain[0], -1)


def tints(piece, document):
    """((shades, layers), record): a prepared piece's tint texture, each material on the channel its brief names.
    A belt's faces turned toward the body are no metal's (`body_side`)."""
    count = len(document['materials'])
    found = texture.materials(piece['rgb'][piece['covered']], count)
    worn = brief.worn(document, found)
    kinds = [material['kind'] for material in worn]
    channel = [brief.tinted(material) + str(material.get('channel', 1)) for material in worn]
    size, amount = len(piece['rgb']), float(document.get('wear', 0))
    hidden = body_side(piece, document, [brief.tinted(material) for material in worn], size)
    lit = texture.lit_shades(piece['rgb'][piece['covered']], found)
    span = float(np.ptp(piece['src'], axis=0).max())
    tinted = texture.tint_maps(
        piece['rgb'], piece['covered'], found, channel, relief=piece['relief'], charts=texture.chart_map(piece['uv'], piece['f'], size), lit=lit, trim=hidden,
        sharpen=texture.SHARPEN, wear=(amount, kinds, *texture.wear_fields(piece['uv'], piece['f'], piece['src'], size, span)) if amount else None)
    record = {'materials': [{'name': material['name'], 'kind': material['kind'], 'channels': [channel[k]],
                             'colour': np.round(found['colours'][k] * 255).astype(int).tolist(), 'lit': round(float(lit[k]), 1),
                             **({'suggested': material['suggested']} if 'suggested' in material else {})}
                            for k, material in enumerate(worn)], **({'wear': amount} if amount else {})}
    return tinted, record


def worn_under(body_pack, body, bones, skin, outfit=None):
    """{part: (vertices, faces)} of what a belt lies on, in body space: the parts of `WORN_UNDER` as the outfit
    `outfit` = (pack folder, number) has them, and the body's own skin where it has none (or there is no outfit).
    A pack folder that is not there is refused: every part would be read as the bare skin, and the record would
    still name the outfit."""
    require(outfit is None or Path(outfit[0]).is_dir(), f'{outfit and outfit[0]} is no pack folder to fit over')
    under = {}
    for token in WORN_UNDER:
        path = None if outfit is None else Path(outfit[0]) / (registry.model_name(body, token, outfit[1]) + '.mdl')
        if path is not None and path.is_file():
            under[token] = measure.mesh(path.read_bytes(), path.stem, bones[seams.BONES[token]])
        elif token in skin:
            under[token] = skin[token]
    require(under, f'Nothing of {body} is found to wear the belt on')
    return under


def surface_failures(whole):
    """The failures of a generated piece as `bake.surface` found it: its openings and its loose pieces."""
    if whole is None:
        return []
    return ([f'the generated piece: an opening {hole * 100:.1f} cm round' for hole in whole['holes']]
            + [f'the generated piece: a piece of {loose * 1e4:.1f} cm² standing apart from the rest' for loose in whole['debris']])


def gates(part, under, model, resources, packs=(), whole=None):
    """The automatic gates of one fitted accessory: a report as `bake.gates` writes one.

    Budgets (`BUDGET`), no triangle the model compiler drops, no name a pack holds, texture closure, the
    generated piece whole (`whole`, what `bake.surface` found), and clearance: no point of the piece more than
    `INSIDE` inside what is worn under it at rest, which is what would show cloth or skin through it."""
    resources, failures = Path(resources), []
    faces = int(len(part['f']))
    if faces > BUDGET['triangles']:
        failures.append(f'{faces} triangles, over the budget of {BUDGET["triangles"]}')
    if len(part['rgb']) > BUDGET['texture']:
        failures.append(f'a texture of {len(part["rgb"])} texels a side, over the budget of {BUDGET["texture"]}')
    corners = np.asarray(part['v'], float)[np.asarray(part['f'], int)]
    collapsed = int(sum((np.linalg.norm(corners[:, i] - corners[:, j], axis=1) < baking.POINT) for i, j in ((0, 1), (1, 2), (2, 0))).astype(bool).sum())
    if collapsed:
        failures.append(f'{collapsed} triangles with two corners at one point, which the model compiler drops')
    for pack in packs:
        if (Path(pack) / (model + '.mdl')).exists():
            failures.append(f'{model}: {pack} holds a model of that name')
    if not (resources / (model + '.plt')).is_file():
        failures.append(f'{model}: no tint texture')
    material = resources / (model + '.mtr')
    if not material.is_file():
        failures.append(f'{model}: no material file')
    else:
        named = [line.split()[1] for line in material.read_text(encoding='ascii').splitlines() if line.startswith('texture') and len(line.split()) > 1]
        failures += [f'{model}: its material file names {image}, which is not there' for image in named if not (resources / (image + '.tga')).is_file()]
    failures += surface_failures(whole)
    points = measure.surface_points(np.asarray(part['v'], float), np.asarray(part['f'], int), SURFACE)
    deepest, where = 0.0, None
    for name, (v, f) in under.items():
        v, f = np.asarray(v, float), np.asarray(f, int)
        # only a point no farther from the part's own axis than its surface reaches at that height and direction
        # can be inside it: a winding number is read for those alone (100,000 points against 8,000 faces took minutes)
        axis = v.mean(axis=0) * [1.0, 1.0, 0.0]
        reach = {}
        worn_way, worn_level, worn_radius = _cells(measure.surface_points(v, f, SURFACE) - axis)
        for key, value in zip(zip(worn_way.tolist(), worn_level.tolist()), worn_radius.tolist()):
            if value > reach.get(key, 0.0):
                reach[key] = value
        way, height, radius = _cells(points - axis)
        near = np.array([any(radius[i] <= reach.get(((way[i] + a) % DIRECTIONS, height[i] + b), -1.0) + SURFACE for a in (-1, 0, 1) for b in (-1, 0, 1))
                         for i in range(len(points))])
        inside = np.zeros(len(points), bool)
        if near.any():
            inside[near] = np.abs(measure.winding(points[near], v, f)) >= 0.5
        if inside.any():
            depth = float(baking._off(points[inside], [(v, f)], near=0.08).max())
            if depth > deepest:
                deepest, where = depth, name
    if deepest > INSIDE:
        failures.append(f'{model}: up to {deepest * 100:.1f} cm inside the {where} worn under it')
    return {'passed': not failures, 'failures': failures, 'triangles': faces, 'texels': int(len(part['rgb'])),
            'inside': {'deepest': round(deepest, 4), 'part': where}, **({} if whole is None else {'surface': whole})}


def fit(document, kept, output, body_pack, number, *, body='pmh0', outfit=None, drop=DROP, turn=0.0, tier=2, packs=(), game=None, resources=(),
        say=lambda *_: None):
    """Put a prepared belt on `body` and check it: the record, also written as `<output>/bake.json`.

    `kept` is the folder `prepare`'s piece is stored in. `outfit` = (pack folder, number) is the outfit the
    belt is fitted over, read as compiled models; without it the belt lies on the body's skin. `drop` is how far
    below the waist joint the band's middle goes, `turn` degrees the hoop is turned about the body's axis
    first (a generation whose front is not the camera's). `tier` is the tier of the set the belt belongs to, which
    its registry part gives its waist and a publication holds the record to. With `game` the model is compiled."""
    require(document.get('accessory') == 'belt', 'Only a belt is fitted this way so far')
    require(tier in registry.TIERS, f'A tier is one of {list(registry.TIERS)}')
    piece, whole = stored(kept)
    bones, skin = measure.body(body_pack, body)
    under = worn_under(body_pack, body, bones, skin, outfit)
    point = np.asarray(seams.plane(bones, 'waist', 'c')[0], float)
    centre = np.array([point[0], point[1], point[2] - drop])
    angle = np.radians(turn)
    spin = np.array([[np.cos(angle), -np.sin(angle), 0.0], [np.sin(angle), np.cos(angle), 0.0], [0.0, 0.0, 1.0]])
    placed, record = wrap(piece['v'] @ spin.T, piece['f'], list(under.values()), centre)
    say('wrapped', record)
    part = {**piece, 'v': placed, 'n': export.vertex_normals(placed, piece['f'])}
    tinted, colours = tints(piece, document)
    ascii_dir, written = Path(output) / 'ascii', Path(output) / 'resources'
    for made in (ascii_dir, written):
        made.mkdir(parents=True, exist_ok=True)
    model = export.write_part(ascii_dir, body, 'belt', number, (part['v'], part['f'], part['uv'], part['n']), bones, tinted)
    texture.write_relief(written, model, part['relief'])
    shutil.copyfile(ascii_dir / (model + '.plt'), written / (model + '.plt'))
    record = {'model': document['model'], 'body': body, 'tier': tier, 'number': number, 'models': {'belt': model}, **colours, 'fit': record,
              'over': None if outfit is None else {'pack': Path(outfit[0]).name, 'number': outfit[1]},
              'gates': gates(part, under, model, written, packs, whole)}
    if game is not None:
        compiled = export.compile_models([ascii_dir / (model + '.mdl')], written, game=game, resources=list(resources))
        record['compiled'] = len(compiled)
    (Path(output) / 'bake.json').write_text(json.dumps(record, indent=1) + '\n', encoding='utf-8', newline='\n')
    np.savez_compressed(Path(output) / 'fitted.npz', v=part['v'], f=part['f'])
    return record
